export const meta = { name:'dedup-recheck', description:'Re-check each collection for remaining too-similar premises after rewrites', phases:[{title:'Dedup recheck'}] }
const LISTS = {"taiwan": ["\"Story 01: Boba and the Midnight Market\" :: theme **Theme:** Courage to explore", "\"Story 02: Taro and the Purple Typhoon\" :: theme **Theme:** Patience and strength", "\"Story 03: Aiyu and the Mountain Spring\" :: theme **Theme:** Honesty and transparency", "\"Story 04: Mochi and the Stretchy Escape\" :: theme **Theme:** Friendship", "\"Story 05: Grass Jelly and the Cool Shadow\" :: theme **Theme:** Being yourself", "\"Story 06: Pineapple Cake and the Golden Gift\" :: theme **Theme:** Generosity", "\"Story 07: Shaved Ice and the Summer Meltdown\" :: theme **Theme:** Impermanence", "\"Story 08: Mango and the Sunshine Race\" :: theme **Theme:** Making the most of your season", "\"Story 09: Red Bean and the Warm Heart\" :: theme **Theme:** Nurturing others", "\"Tangyuan and the Lantern Festival\" :: theme **Theme:** Family and togetherness", "\"Douhua and the Silky Dream\" :: theme **Theme:** Quiet strength", "\"Lychee and the Forbidden Tree\" :: theme **Theme:** Don't judge by appearances", "\"Passion Fruit and the Sour Dare\" :: theme **Theme:** Being bold", "\"Sweet Potato and the Underground Adventure\" :: theme **Theme:** Humility and hidden treasure", "\"Coconut Jelly and the Beach Party\" :: theme **Theme:** Going with the flow", "\"Egg Waffle and the Night Market Showdown\" :: theme **Theme:** Performing for joy", "\"Pudding and the Wobble Contest\" :: theme **Theme:** Embracing imperfection", "\"Sesame Ball and the Golden Roll\" :: theme **Theme:** Bravery needs heart", "\"Starfruit and the Five-Pointed Wish\" :: theme **Theme:** Dreams and perseverance", "\"The Grand Dessert Reunion\" :: theme **Theme:** Community and celebration", "\"Boba and the Midnight Demon Parade\" :: theme **Theme:** Sharing makes you whole", "\"Grass Jelly and the Stinky Tofu Demon\" :: theme **Theme:** Don't judge by smell (or appearance)", "\"Egg Waffle and the Demon Chicken Festival\" :: theme **Theme:** The best shows end with a bang", "\"Mochi and the Demon Slumber Party\" :: theme **Theme:** Love stretches to fit everyone", "\"Tāng Yuán and the Demon King's Midnight Snack\" :: theme **Theme:** Everyone deserves warmth", "\"Mango and the Dessert Track Meet\" :: theme **Theme:** Find your event, run your race", "\"Three Tadpoles and the Glass-Bottom Gondola\" :: theme **Theme:** Big adventures in small bodies", "\"Willa Wobble and the Crazy 8 Tryouts\" :: theme **Theme:** Rest is part of the work — believe in your small self", "\"Aiyu and the Firefly Forest\" :: theme **Theme:** Your quiet glow lights the way for others", "\"Sesame Ball and the Marble Canyon\" :: theme **Theme:** Keep your momentum — steady courage rolls through anything", "\"Pudding and the Midnight Train\" :: theme **Theme:** It's okay to wobble — you still arrive", "\"Red Bean and the Winter Solstice\" :: theme **Theme:** Warmth shared in the cold — food is love", "\"Story 33: Beef Noodle & the Steamy Stadium\" [Niú Niú] :: At Taipei's grand Beef Noodle Festival, newcomer Niú Niú is too shy to enter the slurp-off until he learns the contest isn't about the biggest bowl but the warmest one. He teams up with shivering latecomers to share his steam.", "\"Soup Dumpling & the Steamer-Stack Sleepover\" [Xiǎo Lóng] :: Xiǎo Lóng is convinced the only place worth being is the very top steamer basket, where everyone gets served first. He scrambles and squeezes his way up, only to find the top is drafty and lonely — while the cozy warm middle baskets, where the steam gathers and friends are packed close, were the best spot all along.", "\"Story 35: Scallion Pancake & the Great Flip-Off\" [Cōng Cōng] :: Cōng Cōng challenges the whole street to a pancake-flipping contest but keeps flipping himself into trouble, until anxious Pudding accidentally out-wobbles everyone and the two combine talents.", "\"Story 36: Oyster Omelet & the Tide-Pool Song\" [Wō Wō] :: Shy Wō Wō can barely speak above a whisper until the little oysters in her omelet go quiet from homesickness, and she finds her voice singing them a sea-lullaby that carries across the whole market.", "\"Stinky Tofu & the Lights-Out Hide-and-Seek\" [Chòu Chòu] :: During a lights-out game of hide-and-seek in the twisty alleys, the little snacks get hopelessly lost in the dark. Chòu Chòu, who usually tries to hide his powerful aroma, realizes his unmistakable smell is the one thing that can guide every lost player back to the group — and for once he proudly lets his scent lead the way home.", "\"Story 38: Gua Bao & the Folded Hug\" [Guā Bāo] :: On a rainy night, Guā Bāo keeps her diner warm by folding lost and lonely snacks into cozy hugs, until she runs out of room and the snacks learn to fold one another.", "\"Story 39: Popcorn Chicken & the Runaway Giggle\" [Kǎ Kǎ] :: The Kǎ Kǎ nuggets giggle so hard they scatter across the night market, and the smallest nugget must hop bravely from stall to stall to gather the whole bouncy crew back together before closing.", "\"Story 40: Braised Pork Rice & the Humble Bowl\" [Lǔ Ròu] :: When a glittery new dessert cart makes plain Lǔ Ròu feel boring, a hungry, tired traveler reminds him that a humble warm bowl is exactly the comfort the world needs at the end of a long day.", "\"Story 41: The Savory Squad & the Midnight Feast\" [Niú Niú] :: The new savory friends throw a midnight feast but argue with the dessert crowd over who rules the night market, until a hungry crowd proves a perfect night needs both sweet AND savory.", "\"Story 42: Tea Egg & the All-Night Store\" [Dàn Dàn] :: Wise little Dàn Dàn reads the cracks in his shell like fortunes to comfort late-night wanderers who stop by the all-night store, and helps a lost traveler find the way home.", "\"Story 43: Soy Milk & Youtiao & the Sunrise Dip\" [Yóu Tiáo] :: Goofy Yóu Tiáo is terrified of his big morning dunk into warm soy milk until best pal Dòu Jiāng promises to catch him; together they wake the whole sleepy city with the smell of breakfast.", "\"Story 44: Radish Cake & the Breakfast Club\" [Luóbo Gāo] :: Dependable Luóbo Gāo organizes the breakfast crew for the morning rush, but a sleepy mix-up sends everyone to the wrong stalls; he must keep his cool (and crispy edges) to set the morning right.", "\"Story 45: Pepper Bun & the Clay-Oven Jump\" [Hú Jiāo] :: Hú Jiāo is too scared to make the big jump off the blazing clay-oven wall when he's done baking, until popcorn chicken and friends form a soft, giggling landing pile below.", "\"Story 46: Chicken Cutlet & the Bigger-Than-Your-Face Show\" [Pái Pái] :: Crowd-favorite Pái Pái loves being the biggest snack in the market until a tiny shy nugget gets stage fright; she gives up her spotlight to share the stage and discovers the warmest applause of all.", "\"Story 47: Tangyuan & the Thousand Sky Lanterns\" [Tāng Yuán] :: At the Pingxi festival, Tāng Yuán helps a nervous newcomer write and release their very first sky lantern, learning that the brightest wishes are the ones we send up for someone else.", "\"Story 48: Mooncake & the Mid-Autumn Moon\" [Yuè Bǐng] :: Elegant Yuè Bǐng hosts a rooftop reunion, but the moon hides behind clouds; he gathers everyone to glow together so warmly that the moon peeks out to join the party.", "\"Story 49: Zongzi & the Dragon-Boat Race\" [Zòng Zi] :: Bundled-up Zòng Zi worries he's tied too tight to ever be fast, but in the splashy dragon-boat race he learns his snug wrapping is exactly what keeps his treasures safe through the wildest rapids.", "\"Story 50: The Grand Festival of Fifty Lights\" [Boba] :: To mark fifty stories of adventures, Boba rallies sweet and savory friends to light a chain of lanterns from north to south Taiwan, celebrating how far this growing family has come.", "\"Story 51: Aiyu & the Lantern Riddle Night\" [Aiyu] :: Shy, translucent Aiyu is too timid to shout out answers at the lantern-riddle festival, but her honest, clever whispers solve the trickiest riddle of the night and light the grandest lantern.", "\"Turnip Cake & the Lucky-Word Banner\" [Cài Tóu Guǒ] :: On New Year's Eve, shy Turnip Cake is asked to write the lucky red banner for the door but freezes, afraid his clumsy brushstrokes will jinx the whole year. He discovers the banner isn't about perfect calligraphy — it's about naming the hopes you hold for the people inside, and his wobbly, heartfelt characters become the warmest welcome on the street.", "\"Story 53: The Earth God & the Lucky Corner\" [Tǔdì Gōng] :: The kindly tiny Earth God notices a forgotten corner of the market feeling lonely, and with lucky candies and gentle nudges he helps the snacks there find their place and their friends.", "\"Story 54: Moon Rabbit & the Mochi-Pounding Lullaby\" [Yù Tù] :: High on the moon, the dreamy Moon Rabbit pounds mochi to a lullaby beat, and when Mochi floats up on a moonbeam to help, the two send sweet sleepy dreams drifting down over the whole island.", "\"Story 55: The Little Tiger God Under the Table\" [Xiǎo Hǔ Yé] :: The plump little clay Tiger God is lonely guarding the temple all by himself, until Braised Pork Rice shares his lunch and the two become the coziest guardian duo on the block.", "\"Story 56: Aiyu & the Friendly Mist Spirits\" [Aiyu] :: Tiny, shy mist spirits keep getting lost in the mountain fog and bumping into things; honest Aiyu, who can see clearly through her translucent self, gently guides each one safely home.", "\"Story 57: Tea Leaf & the Cloud Sea of Alishan\" [Ā-Lǐ] :: Calm tea-leaf Ā-Lǐ teaches an impatient young leaf that rushing only makes you bitter; together they wait for the perfect sunrise over the cloud-sea and unfurl their fragrance to greet the day.", "\"Story 58: The Lucky Cat & the Incense-Curl Wishes\" [Tǔdì Gōng] :: A worried little snack comes to the temple with a wish too small to say out loud; the gentle Earth God and a friendly waving lucky-cat statue show that no kind wish is ever too small to matter.", "\"Story 59: Taro & the Southern Sugar Fields\" [Taro] :: Patient Taro begins an island road trip in the sunny south, riding the old sugar-train through cane fields and teaching a restless brown-sugar friend that the sweetest things ripen slowly.", "\"Story 60: Mango & the Mango Capital Race\" [Mango] :: Speedy Mango races through Taiwan's mango capital during peak harvest, but slows down to help a sun-wilted little mango find shade, learning that the best races leave no friend behind.", "\"Sweet Potato & the Lantern-Float River Night\" [Dìguā] :: At the river's floating-lantern night, a little snack clutches a worry he can't bear to release onto the water. Street-smart Sweet Potato — who once buried himself deep in the earth and had to let the farmer dig him up — gently shares that letting a thing drift away can be the bravest move of all, and together they set the worry-lantern gently onto the current.", "\"Story 62: Coconut Jelly & the Kenting Tide\" [Coconut Jelly] :: Chill surfer Coconut Jelly teaches the new savory crew to ride the gentle Kenting waves, but when a sudden tide sweeps a friend out, he learns even the most laid-back dude must paddle hard for the ones he loves.", "\"Story 63: Boba & the Train Around the Island\" [Boba] :: Bouncy Boba sets off to ride the train all the way around Taiwan, collecting a snack friend at every station, until the whole carriage becomes a rolling, laughing party of new and old pals.", "\"Nougat & the Borrowed-Umbrella Chain\" [Niúgá Táng] :: Caught in a downpour, Nougat is lent an umbrella by a stranger who says only 'pass it on when you can.' Instead of keeping the cozy umbrella, Nougat starts a chain of lending it down the rainy street, and by nightfall a single borrowed umbrella has kept a dozen soggy snacks dry — proving a kindness shared keeps spreading long after you let it go.", "\"Story 65: Douhua & the Beitou Hot Spring\" [Douhua] :: Gentle Douhua leads a tired group of friends to soak in the warm Beitou hot springs, where she teaches a frazzled, overheated Pepper Bun the quiet art of letting tension melt away in the steam.", "\"Story 66: Red Bean & the First Warm Day of Spring\" [Red Bean] :: As the last frost lifts, nurturing Red Bean cooks a warm welcome-spring soup under the cherry blossoms, coaxing sleepy hibernating snacks to wake up gently to the new season.", "\"Story 67: Shaved Ice & the Plum Rain Season\" [Shaved Ice] :: During the endless plum-rains, dramatic Shaved Ice melts with worry that nobody wants cold treats in soggy weather, until she learns to throw the coziest rainy-day party the market has ever seen.", "\"Story 68: Mango & the Cozy Typhoon Day\" [Mango] :: Speedy Mango is grumpy that a typhoon cancels his big race, until friends turn the rainy indoor day into the most fun pillow-fort, board-game, and snack adventure of the whole summer.", "\"Candied Tomato & the Worry-Jar Wishing Well\" [Niúfān Qié] :: Candied Tomato keeps every single one of her worries bottled in little jars, terrified to let them go. At the old wishing well she learns that you can't toss in a hopeful coin if both hands are full of worry-jars — so she gently sets her worries down, frees her hands, and helps a frightened friend cast the very first wish of their life.", "\"Pearl Barley & the Counting-Stars Sleepover\" [Yìrén] :: The Pearl Barley grains never stop chattering, and at the rooftop sleepover their nonstop talking keeps everyone awake. One grain learns that when you finally hush and look up, the quiet between words is where the biggest, most wonderful thoughts have room to grow — and counting stars together in silence is its own kind of conversation.", "\"Hot Pot Mochi & the Frozen-Lake Skating Wobble\" [Shāo Má Shǔ] :: On the rare day the high mountain lake freezes, Toasted Mochi wants to ice-skate gracefully on his very first try and is crushed every time he flops onto his squishy bottom. With friends cheering each tumble, he learns that every fall is a step toward gliding — and by sunset his wobbly, giggly skating has turned into the happiest, most fearless slide on the whole lake.", "\"Story 72: Egg Waffle & the Ring-Toss Champion\" [Egg Waffle] :: Showman Egg Waffle is determined to win every night-market game stall in one night, but learns the real prize is helping a nervous newcomer finally win their very first goldfish-scoop.", "\"Almond Tofu & the Cloud-Sorting Job\" [Xìngrén Dòufu] :: Fussy Almond Tofu is hired to sort the teahouse's drifting clouds into neat fluffy rows for the view, but the clouds keep blending and swirling no matter how hard he tidies. He learns that the messiest, mingled cloud-sea is the most beautiful sight of all, and that some lovely things can't — and shouldn't — be kept in tidy lines.", "\"Tempura Fishcake & the Hot-Spring Egg Race\" [Tián Bù Lǎ] :: When a crowd of snacks rushes to soft-boil their eggs in the famous hot springs all at once, they snatch them out too early and end up with a runny mess. Methodical Tianbula shows them that the trick isn't speed — it's lowering one egg gently, timing it just right, and waiting patiently for the perfect, jiggly result everyone's been hurrying past.", "\"Story 75: Passion Fruit & the Sour-Dare Derby\" [Passion Fruit] :: Prankster Passion Fruit runs a sour-face dare derby, daring everyone to the most pucker-worthy challenges, until shy Stinky Tofu out-dares them all by bravely being himself — the boldest dare of all.", "\"Story 76: Boba & the Great Bubble-Tea Shake-Off\" [Boba] :: In Taichung, the home of bubble tea, Boba competes in a shake-off to be the star pearl, but learns that the best cup is the one where brown sugar, tea, and pearls all dance together.", "\"Salty Crisp Chicken & the Spice-Drawer Mystery\" [Yán Sū Jī] :: When the stall's beloved spice drawer goes missing right before the morning rush, self-styled detective Salty Crisp Chicken cracks the case not by being the biggest or boldest but by asking 'why' and 'why' and 'why' again, following a trail of fragrant basil leaves to a sleepy mouse who only wanted to smell something nice.", "\"Story 78: Willa Wobble & the Night-Market Pinball Quest\" [Willa Wobble] :: Crossover guest Willa Wobble, tiniest of penguins, visits the night market and proves that being small is an advantage in the bounciest pinball quest, with Boba bouncing along as her lucky ball.", "\"Story 79: Egg Waffle & the Big Talent Show\" [Egg Waffle] :: Egg Waffle organizes a market talent show and panics when no one signs up; he learns to coax out everyone's hidden talents — even Tea Egg's quiet fortune-reading — for the warmest show ever.", "\"Bubble Waffle Sisters & the Kite Festival Sky\" [Shuāng Bāo Tāi] :: The Double-Bun Twins want to launch the grandest kite at the festival, but one twin yanks the string tight while the other lets it loose, and their kite keeps nose-diving. They learn that flying isn't about one of them winning the tug — it's about feeling the wind together and pulling at the same gentle moment.", "\"Lychee & the Hand-Me-Down Fan\" [Lìzhī] :: Fancy Lychee is mortified that her elegant new silk fan tears on the hottest day, and turns up her nose at the worn, faded paper fan an old fruit-seller offers her. But the shabby little fan turns out to have been hand-painted with love and to cool better than any fancy one — teaching Lychee that worth and beauty hide in well-loved old things, not just new finery.", "\"Iron Egg & the Lost-and-Found Lighthouse\" [Tiě Dàn] :: Crusty little Iron Egg is sure his hard, wrinkled shell means he's no good for soft jobs, until the harbor lighthouse keeper falls ill and a fog rolls in. Iron Egg discovers his dark, dense little body is the perfect weight to keep the signal-lantern's pulley steady, and his gruff foghorn voice gently calls every lost fishing-snack safely back to the docks.", "\"Brown Sugar & the Slow-Drip Mooncake Clock\" [Hēi Táng] :: Theatrical Brown Sugar wants his famous syrup ready in a flash for the festival crowd, but the old teahouse water-clock insists good brown-sugar syrup must drip and thicken slowly, drop by drop, all night. As he waits, he learns that the deep, dark, glorious flavor everyone loves is the gift of patience — and rushing would have ruined it.", "\"Story 84: Peanut Ice Roll & the Weird-Delicious Stand\" [Bǐng Bǐng] :: Cool maverick Bǐng Bǐng (peanut candy, ice cream, and cilantro in a wrap) opens a 'weird-delicious' stand that everyone doubts, until his surprising combo wins over the most stubborn skeptic in the market.", "\"Cuttlefish Ball & the Tangled Lantern Strings\" [Huāzhī Wán] :: Determined to hang all the festival lanterns himself, springy Cuttlefish Ball bounces around tying strings until he's hopelessly tangled in a giant knot of lantern cords. Too proud to call out at first, he finally squeaks for help — and learns that the knot loosens in minutes when many hands each take one string, while one frazzled snack could never undo it alone.", "\"Sago Pudding & the Sandcastle That Wouldn't Stay\" [Xī Mǐ Lù] :: Sago Pudding helps a heartbroken little friend build the grandest sandcastle on the beach, only for the tide to wash it away. Instead of sadness, gentle Sago Pudding shows that the fun was in the building, the castle lives on in their memory, and tomorrow's beach is a fresh blank canvas — teaching that some lovely things are meant to be temporary and that's exactly what makes them special.", "\"Wintermelon Tea & the Sound-Collector's Jar\" [Dōngguā Chá] :: Chatty Wintermelon Tea loves collecting interesting sounds in empty glass jars, but when a lonely new snack arrives who is too sad to speak, his jars stay empty. He learns to stop talking and simply listen — and discovers that letting someone be heard is the most generous gift of all, filling his quietest jar with the truest sound.", "\"Peanut Brittle & the Stuck-Together Day\" [Huāshēng Táng] :: Busy, always-rushing Peanut Brittle prides himself on getting everything done fast, until a sticky-humid day makes the whole workshop go gooey and slow. Forced to wait for the candy to set, he finally sits still long enough to really talk to the quiet little peanut who has been stuck beside him the whole time — and finds his oldest friend was right there all along.", "\"Sun Cake & the Sundial Garden\" [Tàiyáng Bǐng] :: Sun Cake wants the garden's rare night-blooming flower to open NOW so he can show his visiting friends, and keeps trying to pry the petals apart. The old sundial teaches him to read the slow turning of the day and wait for exactly the right moment — and when the flower finally unfurls on its own at dusk, the patience makes it ten times more magical.", "\"Story 90: The Great Night-Market Blackout\" [Grass Jelly] :: When the night market's lights blink out, cool-headed Grass Jelly keeps everyone calm while glowing snacks (Aiyu, Starfruit, Mooncake) light the way and a candlelit feast turns the dark into the coziest night ever.", "\"Story 91: The Hundred-Snack Cooking School\" [Lǔ Ròu] :: Humble Lǔ Ròu and the savory elders open a cooking school to teach a new batch of tiny snacks the cherished old recipes, learning that teaching is its own delicious reward.", "\"Story 92: Boba & the Letter to Every Friend\" [Boba] :: Boba decides to invite every friend — sweet and savory, near and far — to a great gathering, and bounces all over Taiwan delivering hand-written letters, gathering stories along the way.", "\"Story 93: The Earth God & the Island-Wide Blessing\" [Tǔdì Gōng] :: The kindly Earth Gods of every little corner join hands one festival night to bless the whole island and its snacks, lighting a gentle golden warmth from mountains to sea ahead of the big reunion.", "\"Story 94: Tea Egg & the Map of Cracks\" [Dàn Dàn] :: Wise Tea Egg realizes the crackle-lines on his shell form a map of every friend's journey, and he uses it to guide all the scattered snacks toward the gathering place for the grand reunion.", "\"Story 95: The Sweet-and-Savory Cook-Off Truce\" [Niú Niú] :: A friendly cook-off between the Savory Squad and the dessert crew threatens to split the family in two right before the reunion, until they discover the winning dish is one they make together.", "\"Lantern Squid & the Tide-Chart Crossing\" [Yóu Yú Gēng] :: The far-flung island snacks are desperate to set off for the grand reunion right away, but the boat can only cross safely at high tide. Practical Squid Soup reads the old tide-chart and convinces the eager crowd to wait for the perfect moment — and when the tide finally lifts the boat, their patience carries them across smoothly, arriving in time and all in one happy piece.", "\"Story 97: Shaved Ice & the Grandest Decorations\" [Shaved Ice] :: Dramatic Shaved Ice takes charge of decorating the grand reunion hall and goes gloriously overboard, until friends help her see that the warmest decoration is the crowd of friends themselves.", "\"Story 98: The Night Before the Reunion\" [Douhua] :: On the quiet night before the hundredth-story reunion, gentle Douhua moves through the guesthouse soothing excited, sleepless friends, helping the whole family rest up for the biggest day yet.", "\"Story 99: Sunrise Over the Whole Island\" [Dòu Jiāng] :: Dawn-gentle Soy Milk and Youtiao wake the whole island with a warm breakfast as every snack — sweet and savory, old and new — sets out on the morning roads toward the grand hundredth reunion.", "\"Story 100: The Grand Island Reunion\" [Boba] :: At last, every friend from all one hundred stories — sweet and savory, fruit and folklore, new and old — gathers for the grandest reunion feast Taiwan has ever seen, celebrating the family they've become."], "hawaii": ["\"Dole Whip Dani and the Very First Aloha\" [Dole Whip Dani] :: On her very first morning swirled fresh from the machine, Dole Whip Dani learns that the magic island word 'aloha' can mean hello, love, and goodbye all at once, and she sets out to greet every snack on the beach before she melts.", "\"Kai the Shave Ice and the Rainbow That Ran Away\" [Kai the Shave Ice] :: When a sudden rain washes the syrup stripes off Kai and he turns plain white, he and his friends chase the island anuenue to get his rainbow back, only to learn his colors were inside him all along.", "\"Malia the Malasada and the Warm Morning Batch\" [Malia the Malasada] :: Malia is the last warm malasada in the morning batch and wants to keep her sugar all to herself, until a line of hungry, sleepy snacks teaches her that the sweetest word on the island is 'mahalo.'", "\"Musubi Manu and the Bento Backpack Mix-Up\" [Musubi Manu] :: Tidy, reliable Musubi Manu loses his bento backpack full of everyone's lunches and must wikiwiki retrace his steps across the neighborhood, discovering that ohana means nobody's lunch gets left behind.", "\"Poke Pua and the Perfect Bowl\" [Poke Pua] :: Poke Pua is so determined to arrange the most perfect, picture-pretty bowl on the island that she forgets to actually be ono, until a messy, joyful mix-up reminds her that delicious comes from the heart.", "\"Saimin Sam and the Great Noodle Knot\" [Saimin Sam] :: Saimin Sam can't stop swishing his noodles to make them 'perfect' and swirls them into one giant hopeless knot right before the Great Slurp-Off. Tempted to blame the wind, he instead owns the mistake out loud, and the whole stand of soup bowls rallies to untangle his noodles, laughing with him.", "\"The Whole Gang Meets Honu Haupia\" [Honu Haupia] :: The young snacks discover a wise, wobbly haupia honu resting in a tide pool, and she becomes the gentle elder of their growing ohana, promising to guide them on the big adventures to come.", "\"Manapua Mano and the Midnight Snack Mission\" [Manapua Mano] :: When the food stalls call 'pau hana' for the night, hungry Manapua Mano leads a sneaky midnight snack mission that gets gloriously out of hand, teaching the gang that the best snack is shared and on time for bed.", "\"Lilikoi Lani and the Sour Surprise\" [Lilikoi Lani] :: Zesty prankster Lilikoi Lani pulls one sour trick too many and accidentally hurts a friend's feelings, then must get truly akamai to turn her sour surprise into a sweet one.", "\"Mac the Macadamia and the Little Big Rescue\" [Mac the Macadamia] :: Tiny, shy Mac is always overlooked until a friend gets stuck on a narrow cliff ledge, and only someone small, smooth, and wikiwiki can roll to the rescue and prove that small but mighty is no joke.", "\"Kalua the Pig and the First Big Luau\" [Kalua the Pig] :: Gentle Kalua the Pig has roasted low-and-slow all day in his cozy ti-leaf blanket for the island's first big luau, and as the torches light up he joyfully takes center plate, beaming that becoming the feast is the proudest moment of his life.", "\"Poi Popo and the Old Island Stories\" [Poi Popo] :: As the luau winds down, grandparent Poi Popo gathers the keiki under the banyan tree to share the old story of the taro plant and teach them aloha aina — that loving the land is loving your family.", "\"Pua the Pineapple and the Crooked Crown\" [Pua the Pineapple] :: Vain Pua the Pineapple is so haaheo of her leafy crown that she refuses to let anyone share the luau spotlight, until her crown goes crooked and humble friends show her what real pride looks like.", "\"Lani the Loco Moco and the Lazy Sunday Feast\" [Lani the Loco Moco] :: Hearty Lani the Loco Moco insists the whole busy gang slow down for one nanea rainy-Sunday feast, proving that sometimes the most loving thing an ohana can do is rest and eat together.", "\"The Lei of Many Flowers\" [Malia the Malasada] :: Malia gathers all her different friends to string a giant welcome lei for a family party and learns that the most beautiful lei, like the best ohana, is made of many different flowers woven side by side.", "\"The Hula Everyone Forgot\" [Honu Haupia] :: Honu Haupia teaches the wobbly, clumsy gang an old hula whose meaning was nearly forgotten, and the keiki discover that every sway and step tells a story of the islands.", "\"Musubi Manu and the Grandparent's Recipe\" [Musubi Manu] :: Musubi Manu wants to make his kupuna's secret musubi exactly right for the family gathering, but a missing ingredient teaches him that the real recipe is the love and patience passed down through the family.", "\"The Luau Where Everyone Belonged\" [Kalua the Pig] :: Kalua the Pig hosts a grand neighborhood luau where Hawaiian, Japanese, Portuguese, Chinese, and Filipino snacks all bring a dish, and through kokua they discover that the islands' magic is everyone belonging at one table.", "\"Sailing to Maui on a Coconut Canoe\" [Niu the Coconut] :: Niu the Coconut captains a wobbly little canoe as the gang sets off holoholo across the channel to Maui, and the tough-shelled coconut learns to trust his crew when the wind picks up.", "\"The Road to Hana and the Slow Honu Way\" [Honu Haupia] :: On the famously twisty Road to Hana, impatient friends want to zoom, but Honu Haupia leads them the slow honu way past waterfalls and rainbows, proving the journey is the treasure.", "\"Sunrise on Haleakala\" [Dole Whip Dani] :: Sun-loving Dole Whip Dani drags the sleepy gang up cold, cloud-topped Haleakala to watch the la rise, where they witness the most magical sunrise in the world and learn the meaning of 'house of the sun.'", "\"Kauai, the Garden Island Mystery\" [Lilikoi Lani] :: On the wildly green Garden Island, curious Lilikoi Lani follows a trail of mysterious sweet smells deep into the nahele, leading the gang to a hidden valley of wild fruit and a gentle surprise.", "\"The Waimea Canyon Echo\" [Mac the Macadamia] :: Quiet little Mac is too shy to ever raise his leo, until the giant Waimea Canyon echoes his tiny call into a mighty sound, and he discovers his voice matters and travels farther than he thought.", "\"Molokai and the Friendly Quiet\" [Poi Popo] :: The gang visits sleepy, gentle Molokai where there are no big towns, and elder Poi Popo shows the restless keiki the deep malie of a place that does things the old, unhurried, aloha way.", "\"Lanai, the Pineapple Island Homecoming\" [Pua the Pineapple] :: Proud Pua the Pineapple visits Lanai, once the great Pineapple Island, to meet the fields her makua came from, and the homecoming softens her crown-proud heart into something gentler and truer.", "\"Big Island, Black Sand and Green Sand\" [Kai the Shave Ice] :: Rainbow-colored Kai is amazed to find beaches with jet-black and even green one on the Big Island, learning that the island makes beauty in every color, including ones he never imagined.", "\"The Stars Over Mauna Kea\" [Honu Haupia] :: On the towering, snow-capped Mauna Kea, wise Honu Haupia teaches the keiki how the ancient voyagers read the hoku to sail between islands, and the gang feels small and safe under the brightest stars on Earth.", "\"Poke Pua Learns to Surf\" [Poke Pua] :: Confident Poke Pua assumes she'll be a natural at heenalu, but wipeout after wipeout teaches the ocean-proud bowl that even the freshest fish has to fall a few times before she rides.", "\"The Penguins Who Came to Surf\" [Dole Whip Dani] :: Piper Paddlefoot and her penguin crew swap their snowboards for surfboards and visit Hawaii, where Dole Whip Dani and friends teach them that a nalu is just a wave you ride with your belly instead of snow.", "\"The Big Wave of the North Shore\" [Musubi Manu] :: Steady, dependable Musubi Manu never planned to face the towering North Shore waves, but when a friend drifts out toward the big nalu he must decide if he's truly makaukau to be the brave one.", "\"Honu Haupia and the Gentle Reef\" [Honu Haupia] :: Honu Haupia guides the gang on a snorkel through a glowing coral reef in the kai, and when they find a little fish tangled in a stray bit of net, they learn that aloha means protecting even the tiniest neighbors.", "\"The Dolphins of the Bay\" [Kai the Shave Ice] :: Kai the Shave Ice is dazzled when a pod of spinning nai-a leaps through the dawn bay, and the gang learns the gentle joy of watching wild friends play without crowding them.", "\"The Whale's Winter Song\" [Poi Popo] :: Each winter the great kohola sing their way back to Hawaii's warm waters, and elder Poi Popo tells the keiki how even the biggest travelers return to the islands they love, just like ohana.", "\"Musubi Manu and the Tide Pool Treasures\" [Musubi Manu] :: Practical Musubi Manu organizes a tide-pool treasure hunt and discovers tough little opihi clinging to the rocks, learning that holding on tight to what you love is a kind of strength.", "\"The Night the Sea Glowed\" [Lilikoi Lani] :: On a moonless po, prank-loving Lilikoi Lani is sure the beach will be boring, until the waves light up with glowing blue sparkles and she learns the night holds wonders no daytime trick could match.", "\"The Glow of Pele\" [Pele's Glow] :: The gang meets Pele's Glow, a tiny gentle lava ember who is not scary at all, and learns that the warm, wondrous fire of Pele the volcano is what slowly builds the islands themselves.", "\"How the Island Was Born\" [Pele's Glow] :: Pele's Glow shows the keiki how glowing lava cools, hardens, and slowly becomes brand-new aina where plants will one day grow, teaching the wonder of how Hawaii's land is always being born.", "\"The Warm Black Sand Beach\" [Niu the Coconut] :: Niu the Coconut washes ashore on a beach of warm ele-ele sand born from old lava and meets the honu who nest there, learning that even fierce fire can leave behind something soft and welcoming.", "\"The Rainforest Where the Rain Sings\" [Lani the Loco Moco] :: Cozy Lani the Loco Moco leads the gang into a dripping green rainforest where the ua falls like music, and the snacks learn that the gentle island rain is what keeps all the fruit and flowers so ono.", "\"Macadamia Mac and the Mountain Orchard\" [Mac the Macadamia] :: Mac visits the mauka orchard where he was grown and learns from the patient trees that the slowest-growing nuts and beans become the richest treats, helping him feel proud of taking his time.", "\"Pua the Pineapple and the Field of Gold\" [Pua the Pineapple] :: Now-gentler Pua returns to the great pineapple fields and learns that no pineapple grows alone — it's the lokahi of the whole field, sun, rain, and soil that makes each crown sweet.", "\"The Makai Tide and the Mauka Stream\" [Honu Haupia] :: Honu Haupia follows a stream all the way from the mauka mountains down to the makai sea, teaching the gang the old island wisdom that the mountains and the ocean are one connected family.", "\"Dole Whip Dani and the Melting Day\" [Dole Whip Dani] :: On the most blazing la-la day of the year, Dole Whip Dani starts to melt and is too proud to ask for help, until her friends rush her to cool shade and she learns leaning on your ohana is its own kind of strength.", "\"The Lost Little Malasada\" [Malia the Malasada] :: Sweet Malia gets separated from the gang in a giant, busy food festival and must huli through the crowd, discovering that the island is full of kind strangers who help a lost keiki find her ohana.", "\"Musubi Manu and the First Day of School\" [Musubi Manu] :: On the nervous first day at a new island school, dependable Musubi Manu helps a shy newcomer feel welcome and learns that being someone's first hoa is the best job of all.", "\"Lilikoi Lani and the Aloha Friday\" [Lilikoi Lani] :: It's Aloha Friday and prankster Lilikoi Lani plans the silliest, most hau-oli neighborhood block party ever, learning that the best fun is the kind that makes the whole street smile together.", "\"Manapua Mano and the Quietest Question\" [Manapua Mano] :: Manapua plans the BIGGEST, loudest welcome for the visiting Taiwan snacks (booming drums, spicy dares, giant waves) and overwhelms his tired, shy guests. When he finally goes quiet, he realizes he has shown off all day without ever asking them a single question, and learns that real welcome comes from listening, not performing.", "\"Kamaron the Garlic Shrimp and the Cheering Truck\" [Kamaron the Garlic Shrimp] :: Kamaron is the fastest snack on the beach and wins every single race at the North Shore Beach Games, but each lonely victory feels emptier while the whole crowd roars instead for whoever finishes last. He discovers that the joy was never in finishing first, and chooses to become his friends' loudest cheerleader in the final relay.", "\"The Luau Under the Volcano Stars\" [Kalua the Pig] :: Kalua the Pig leads a grand sunset luau under the warm volcano glow where every friend gives thanks, and the gentle pig joyfully takes center plate one more time, proud to bless the whole ohana with his feast.", "\"The Grand Aloha Reunion\" [Honu Haupia] :: Every snack, fruit, elder, and friend from across all the islands gathers for one last sunset reunion where wise Honu Haupia reminds them that aloha never really says goodbye, only 'a hui hou' — until we meet again."], "costa-rica": ["\"Gallo and Pinto and the Pura Vida Morning\" [Gallo and Pinto] :: Rice grain Gallo and black bean Pinto wake up in the breakfast skillet and learn they are meant to mix together as gallo pinto. They tumble into a joyful sizzling dance and greet the town's sleepy morning with Pura Vida cheer.", "\"Lala Tres Leches and the Three-Milk River\" [Lala the Tres Leches] :: Lala the cake is too dry and crumbly until three friendly milk jugs pour her a gentle river to soak in. She learns patience as she drinks up sweetness and becomes her soft, happy self, thanking each milk.", "\"Tato Patacon and the Big Smash\" [Tato the Patacon] :: A round green plantain named Tato is nervous about being smashed flat, until he discovers the big squish turns him into the crispiest, most tuanis patacon in the soda. He learns that change can be delicious.", "\"Coco Granizado and the Hottest Day\" [Coco the Granizado] :: On the hottest day ever, the towns-folk are wilting until Coco the granizado cart rolls in. Coco races to cool everyone before melting away, learning the joy of being shared rainbow scoop by rainbow scoop.", "\"Don Café and the Slow Sunrise\" [Don Café] :: Don Café the wise coffee bean teaches an impatient young bean that brewing slowly is what makes the whole familia's morning warm and wonderful. The farm wakes up one fragrant sip at a time.", "\"The Casado That Couldn't Agree\" [Gallo and Pinto] :: Rice, beans, salad, and plantain argue about who is the best part of the plate, until Gallo and Pinto remind everyone that a casado is a happy marriage of flavors. They make peace and become the coziest lunch ever.", "\"Flan Coconut and the Wobbly Stage\" [Flan the Coconut Flan] :: Nervous Flan must be the wobbly star of a birthday table but keeps jiggling with stage fright. With his mae Lala cheering, he learns his wobble is exactly what makes everyone smile.", "\"Cajeta de Coco and the Bouncing Marbles\" [Cajeta the Coconut Fudge] :: Tiny coconut-fudge ball Cajeta feels too small among the big desserts, until her perfect roundness lets her bounce to the rescue when the candy jars tumble. She saves the day one sweet bound at a time.", "\"The Little Soda on the Corner\" [Gallo and Pinto] :: The corner soda is too quiet one rainy evening, so Gallo, Pinto, and the gang throw a surprise pot-luck to fill it with laughter, music, and the smell of good food, proving home is the people in it.", "\"Chifrijo and the Layered Friendship\" [Tato the Patacon] :: During a big futbol match, the snack bowl of chifrijo (beans, rice, pork, pico, and patacones) must work in layers to cheer on the team. Tato learns every layer matters, especially the crunchy ones on top.", "\"Slowy the Sloth and the No-Hurry Hike\" [Slowy the Sloth] :: Speedy Cajeta wants to zoom through the selva, but Slowy the sloth teaches her that going slowly reveals hidden flowers, sleepy frogs, and the secret heartbeat of the jungle.", "\"Tico Toucan and the Rainbow-Beak News\" [Tico the Toucan] :: Tico the toucan loves announcing news, but when he gets a story wrong the jungle gets in a flap. He learns to check his facts and uses his big beak to spread kindness instead.", "\"Tamalita and the Banana-Leaf Blanket\" [Tamalita] :: When sudden lluvia soaks the jungle friends, Tamalita shares her cozy banana-leaf wrapping to keep everyone warm and dry, discovering that being wrapped up means she has love to spare.", "\"The Tree Frog Lullaby\" [Slowy the Sloth] :: A shy little red-eyed tree frog is too nervous to add his peep to the nightly jungle lullaby. Slowy gently helps him find his voice, and the whole selva drifts off to the sweetest song.", "\"The Hummingbird and the Hidden Flower\" [Cajeta the Coconut Fudge] :: A tired hummingbird can't find any nectar, so Cajeta and friends help her discover one last hidden flor blooming deep in the green. The grateful hummingbird repays them with a dazzling dance.", "\"The Monkey-Mischief Mango Heist\" [Tico the Toucan] :: A band of giggling capuchin monos keep swiping the jungle's mangoes. Instead of getting cross, Tico organizes a fun fruit-sharing fiesta so the monkeys join in honestly rather than steal.", "\"Slowy and the Firefly Lanterns\" [Slowy the Sloth] :: When the moon hides behind clouds, the jungle gets dark and a lost baby coatí can't find home. Slowy rallies the fireflies to make a trail of gentle luz that guides the little one safely back.", "\"Don Café and the Cloud Forest Climb\" [Don Café] :: Don Café leads a gentle climb up the cloud-forest montaña to greet the resplendent quetzal at dawn, teaching the young beans that the slow path up rewards you with wonders.", "\"Arenal the Gentle Volcano\" [Lala the Tres Leches] :: Friendly volcán Arenal grumbles because nobody visits his warm hot springs anymore. Lala leads the friends in a cozy soak, and the gentle giant happily warms them all like a sleepy fireplace.", "\"The Oxcart Parade Up the Mountain\" [Don Café] :: Don Café and the coffee beans ride a beautifully painted carreta to market, but the hill is steep. The whole familia learns to share the weight, singing all the way up to the highlands.", "\"Poás and the Crater of Stars\" [Coco the Granizado] :: Coco the granizado finally feels at home in the chilly mountain air at Poás, where the crater pool mirrors a sky full of estrellas. He helps shy mountain critters stargaze without fear of the dark.", "\"Olla de Carne, the Big Warm Stew\" [Pinto] :: On a chilly mountain night, root veggies, corn, and beef gather in the big olla for olla de carne stew. Pinto helps the nervous newcomers (yuca, chayote, plantain) see that each adds flavor to the whole.", "\"Cas the Sourpuss and the Sweetest Surprise\" [Cas the Sour Guava] :: Cas, a small puckery green guava, is sure nobody could ever love something so sour, so he hides at the back of the fruit basket while sweet mangoes and bananas get chosen for every fresco. When a too-sweet, sticky-hot afternoon leaves all the syrupy drinks tasting flat and cloying, the blender pitcher begs for just a splash of something bright — and Cas's puckery tang turns the dull fresco into the most refreshing, can't-stop-sipping drink the whole street has tasted. He discovers his sourness was never a flaw; it was the spark everything else was missing.", "\"Chorreado and the Lost-and-Found Spoon\" [Chorreado the Corn Pancake] :: Chorreado, a warm little corn pancake, has lost the one wooden spoon that flips him, and he is far too proud to admit it because everyone thinks he is the most independent breakfast on the shelf. He spends the foggy morning trying to flip himself in increasingly silly ways (rolling, bouncing, asking the fog to gust under him) and keeps landing splat. Only when he finally squeaks out 'ayuda?' do the natilla pot, a curious cloud-forest mouse, and Don Cafe come together to find the spoon tucked under a coffee sack and flip him golden — and he learns that the bravest cooks ask for a hand.", "\"The Quetzal and the Morning Mist\" [Don Café] :: The friends wait quietly in the mist hoping to glimpse the shy emerald quetzal. Don Café teaches them stillness, and they're gifted a single shimmering pluma as a thank-you for their respect.", "\"Coco Granizado and the Pacific Waves\" [Coco the Granizado] :: Coco the granizado heads to the playa to learn surfing but keeps tumbling off the board. A friendly wave teaches him to relax and ride, and he becomes the coolest cone on the coast.", "\"Estrella and the Moonlit Nesting Beach\" [Estrella the Sea Turtle] :: Estrella the sea turtle guides her tiny hatchling tortugas safely to the sea, with the friends dimming their sparkle so the moonlight can lead the babies home across the sand.", "\"The Caribbean Coconut Dance\" [Cajeta the Coconut Fudge] :: On the Caribbean coast, Cajeta the coconut-fudge ball discovers her coconut roots in a joyful calypso baile, learning to celebrate her flavor and culture with rhythm and pride.", "\"The Pelican Fishing Contest\" [Tato the Patacon] :: Tato enters a friendly fishing contest against a show-off pelican but keeps missing every pez. He learns that cheering others and having fun is the real prize, and the pelican shares his catch.", "\"The Tide-Pool Treasure Hunt\" [Estrella the Sea Turtle] :: Estrella leads a tide-pool treasure hunt for a 'lost gem' that turns out to be a sparkling shell anyone could've found. The friends realize the mar's true treasure is the wonder they shared.", "\"The Sandcastle Soda by the Sea\" [Gallo and Pinto] :: Gallo and Pinto set up a beachside soda but the arena keeps getting in the gallo pinto. With everyone's help they build a cozy seaside kitchen and feed the whole sunny playa.", "\"The Dolphin and the Pura Vida Pod\" [Estrella the Sea Turtle] :: A lonely young delfín wants a pod to play with. Estrella and the friends help him find a welcoming pod, and the whole sea bursts into a happy splashing Pura Vida parade.", "\"The Mangrove Night Paddle\" [Coco the Granizado] :: Paddling through the mangroves at night, the friends discover the agua glows blue with every splash. Coco learns that the dark isn't scary when it sparkles with quiet wonder.", "\"Rondon and the Borrowed Pot\" [Rondon the Caribbean Coconut Stew] :: Bubbly coconut stew Rondon has been quietly cross at the Pelican ever since the bird borrowed his big cooking pot and returned it dented. He simmers and sulks all afternoon, refusing to share the seaside supper. But when a sudden evening downpour leaves the whole beach hungry and cold, the dented pot turns out to be the only one wide enough to feed everyone — and the apologetic Pelican shows up with fresh fish to add. Rondon decides the warm meal matters more than the old dent, lets the grudge float out to sea, and the two stir up the coziest shared supper on the shore.", "\"Sopa Negra and the Moonlight Soup\" [Pinto] :: Pinto and his bean cousins gather into a warm pot of sopa negra to comfort a homesick traveler under the luna, proving that humble black bean soup is full of cozy magic.", "\"Pan Bon and the Christmas Eve Mix-Up\" [Pan Bon the Caribbean Sweet Bread] :: Spicy-sweet Pan Bon is so excited for Christmas that he accidentally knocks the whole tray of carefully labeled gift-bundles off the table, jumbling every name tag so nobody knows which present is whose. Terrified of spoiling Navidad, he first tries to sneakily fix it and only makes the tangle worse. When he finally takes a deep breath and says 'perdon, it was me' to the gathered familia, everyone laughs warmly, turns the mix-up into a giggly guessing game, and the night becomes the most memorable Christmas yet — teaching Pan Bon that a brave 'sorry' is the best gift of all.", "\"Arroz con Leche and the Grandma's Recipe\" [Gallo] :: Gallo the rice grain becomes the star of a creamy arroz con leche made from abuela's secret recipe, learning that a pinch of cinnamon and a lot of love is the true secret ingredient.", "\"The Oxcart Festival of Colors\" [Don Café] :: At the famous painted-oxcart fiesta, a plain undecorated carreta feels left out. Don Café and friends help paint it with the colors of all their favorite things, and it leads the grand parade.", "\"Agua Dulce and the Quiet Helper\" [Agua Dulce the Sugarcane Drink] :: While everyone dances and feasts at the marimba fiesta, warm sweet Agua Dulce keeps the whole party going from the sidelines — refilling cups, soothing tired feet, warming up chilly dancers — yet no one notices the humble cup of sugarcane drink doing all the unglamorous work. When the fiesta suddenly droops because the dancers are exhausted and the band is parched, Agua Dulce quietly revives them all, and Don Cafe gently points out who's been holding the night together. The square stops to give Agua Dulce a great big 'gracias,' and Agua Dulce learns that being a quiet helper is its own special kind of shining.", "\"Churchill and the Half-Time Repair\" [Churchill the Puntarenas Shaved-Ice Sundae] :: During the tense national futbol final, the snacks get so worked up that two old friends — a plantain chip and a bean dip — start a sharp argument over who jinxed the team, and the cozy watch-party turns frosty. Towering, syrup-topped Churchill, the famous Puntarenas shaved-ice sundae, glides in at half-time and instead of taking sides, cools everyone's tempers with a gentle 'calma, amigos,' helping each friend hear the other out. By the time the second half starts, the squabble is patched, and whatever the final score, the friends are watching shoulder to shoulder again.", "\"The Mango-Season Fiesta\" [Cajeta the Coconut Fudge] :: The neighborhood mango tree drops more fruit than anyone can eat, so Cajeta organizes a sharing fiesta with mango everything, teaching that plenty grows sweeter when given away.", "\"Pejibaye and the Wobbly First Kick\" [Pejibaye the Peach-Palm Fruit] :: Round little Pejibaye has watched the recess futbol game from the wall every single day, longing to play but frozen by the thought of missing the ball in front of everyone. When the game needs one more player and nobody will volunteer to take the scary first kick-off, Pejibaye's heart pounds — and he rolls forward anyway, whispering 'valiente, valiente.' His first kick is a wobbly, sideways flub that sends the ball bonking off a tree and back to him for a lucky goal, and the whole yard cheers not for the goal but for the courage it took to go first.", "\"The Rainy-Season Board Game Night\" [Lala the Tres Leches] :: When the green-season rains keep everyone inside, Lala turns a gloomy afternoon into a giggly board-game and storytelling marathon, proving that to jugar with familia beats any sunny day.", "\"The Firefly Birthday Surprise\" [Flan the Coconut Flan] :: It's Don Café's surprise cumpleaños, and worrywart Flan is in charge of keeping it secret. With fireflies as helpers, the friends pull off the wobbliest, most heartfelt birthday surprise ever.", "\"The Lost Puppy and the Warm Casado\" [Pinto] :: A shivering lost perro wanders into town, and Pinto leads the gang to make him a warm casado and find his family, learning that kindness fills both bellies and hearts.", "\"The Pura Vida Pen-Pals\" [Lala the Tres Leches] :: A carta arrives from dessert friends across the sea, and Lala writes back, sharing recipes and Pura Vida cheer. The two faraway dessert families become pen-pals and plan a someday visit.", "\"The Coast-to-Coast Relay\" [Tato the Patacon] :: The friends run a friendly coast-to-coast relay along the camino across Costa Rica, each leg led by a different friend, celebrating the whole country from rainforest to volcano to both shining seas.", "\"The Cloud Forest Lantern Walk\" [Don Café] :: On a peaceful lantern walk, each friend carries a farol up the misty montaña, and together their gentle lights guide all the sleepy jungle animals to a cozy starlit gathering.", "\"The Night the Whole Familia Camped\" [Gallo and Pinto] :: The whole familia camps under a blanket of stars, sharing stories of all their adventures and roasting cajeta over the fire as the cielo fills with falling stars and sleepy yawns.", "\"The Grand Pura Vida Feast\" [Gallo and Pinto] :: Every friend from every arc gathers for one enormous Pura Vida feast — gallo pinto, casado, tamales, tres leches, granizados and all — celebrating a whole collection of love with full bellies and fuller corazones."], "japan": ["\"Momo Mochi and the Tokyo Tower Lights\" [Momo Mochi] :: Newly arrived in the big city, squishy Momo Mochi gets gently lost and follows the warm orange glow of Tokyo Tower, meeting kind food-friends who help her find her way and her first hellos.", "\"Niko Nigiri and the Shibuya Scramble\" [Niko Nigiri] :: Tidy planner Niko Nigiri tries to cross the busiest crossing in the world with a perfect 12-step plan, but learns from his friends that sometimes you just hold hands and go with the flow.", "\"Pock Ramune and the Vending Machine Mystery\" [Pock Ramune] :: Fizzy Pock Ramune discovers a vending machine that dispenses one mysterious warm can every midnight, and gathers friends to gently solve the cozy little secret of who keeps refilling it.", "\"Sora Soft-Cream at the Tokyo Skytree\" [Sora the Soft-Cream] :: Gentle Sora is nervous about heights until friends ride the glass elevator up Skytree with her, where she discovers the whole twinkling city looks like a cozy bowl of stars.", "\"The Dango Three and the Rainbow Train Lines\" [The Dango Three] :: The skewered Dango Three each want a different colored train line, so they invent a fair plan to ride all three and discover the whole rainbow loops back home.", "\"Rin Ramen and the Midnight Yokocho\" [Rin Ramen] :: Steamy Rin Ramen wants to find the very best stall in a tiny lantern-lit alley, but learns the secret ingredient is simply sharing a warm bowl with new friends.", "\"Neko-Pan and the Akihabara Glow\" [Neko-Pan] :: Lucky cat-bun Neko-Pan wanders dazzling Akihabara waving hello to everyone, spreading tiny bits of good luck until the whole street glows a little brighter.", "\"Momo Mochi and the Kotatsu Club\" [Momo Mochi] :: On a cold night, Momo Mochi invites the whole cast under one toasty kotatsu, but when the heat 'goes out' they discover snuggling close keeps everyone warm anyway.", "\"Gacha and the Capsule-Toy Arcade\" [Gacha the Gachapon] :: Gacha rolls down a whole arcade of capsule machines hoping for a rare prize, but discovers the very best surprise is the friends who roll alongside him.", "\"Dora Dorayaki and the Cozy Comic Convention\" [Dora the Dorayaki] :: Story-loving Dora attends his first cozy convention, feels shy about his favorite hobby, then discovers a whole warm crowd who love the very same gentle comics.", "\"Maru Matcha and the Quiet Manga Café\" [Maru Matcha] :: Calm Maru Matcha helps a nervous friend find the perfect first manga in a towering quiet café, learning that everyone's story-shelf is different and that's the magic.", "\"Tako and Yaki and the Cosplay Mix-Up\" [Tako & Yaki] :: The takoyaki twins swap costumes to trick their friends, but the gentle giggly mix-up teaches everyone that you can dress up as anyone and still be wonderfully you.", "\"Neko-Pan and the Cat Café Afternoon\" [Neko-Pan] :: Lucky cat-bun Neko-Pan visits a cat café and learns that the shyest, fluffiest cat just needs slow, gentle patience to come out for a cuddle.", "\"Gacha and the Claw-Machine Rescue\" [Gacha the Gachapon] :: A tiny plush friend is stuck deep in a claw machine, so Gacha rallies the cast to cheer, strategize, and gently win their friend free — together.", "\"Dora Dorayaki and the Robot-Cat Pen Pal\" [Dora the Dorayaki] :: Dora finds a friendly toy robot-cat who collects letters for lonely friends, and helps deliver warm notes across the neighborhood, snack by snack.", "\"Yuki Snow-Monkey and the Steamy Onsen\" [Yuki the Snow Monkey-Manju] :: Snuggly Yuki leads friends to a snowy hot spring, where they soak beside gentle snow monkeys and learn the cozy art of a good warm rest.", "\"Maru Matcha and the Snow-Monkey Friends\" [Maru Matcha] :: Calm Maru Matcha sits very still and whisks warm tea until a shy little snow monkey works up the courage to share the warm steam and become a friend.", "\"Yuki and the Towel-on-the-Head Trick\" [Yuki the Snow Monkey-Manju] :: Yuki teaches friends the cozy onsen custom of folding a tiny towel atop your head, and a silly towel-balancing contest turns into the warmest giggle of the winter.", "\"Sora Soft-Cream and the Mount Fuji Climb\" [Sora the Soft-Cream] :: Soft-serve Sora worries she'll melt before reaching the top of Mount Fuji, but step by patient step she and her friends reach the sunrise summit and watch the sky turn pink.", "\"Dai Daruma and the Mountain of Never-Give-Up\" [Dai Daruma] :: Roly-poly Dai Daruma keeps tumbling down a steep mountain path but bounces right back up each time, cheering his tired friends all the way to the summit shrine.", "\"Kuma Kuri and the Mountain Hot-Spring Eggs\" [Kuma the Kuri] :: Shy chestnut Kuma discovers a spring hot enough to gently cook eggs and quietly prepares a steaming snack for every weary mountain traveler who passes by.", "\"Momo Mochi and the Foggy Ropeway\" [Momo Mochi] :: When fog swallows the mountain ropeway, squishy Momo Mochi keeps everyone calm with a hand-squeeze chain until the clouds part to reveal a breathtaking view.", "\"Maru Matcha and the First Torii Gate\" [Maru Matcha] :: Calm Maru Matcha teaches her friends the gentle custom of bowing at a torii gate, and the quiet little ritual makes the whole shrine feel softly special.", "\"Niko Nigiri and the Thousand Red Gates\" [Niko Nigiri] :: Organized Niko wants to count all thousand red gates at once, but learns to enjoy each glowing gate as it comes, one cozy step at a time.", "\"Dai Daruma and the Wishing Eye\" [Dai Daruma] :: Dai Daruma helps a worried friend pick a real daruma doll and paint its first eye, learning that a wish works best when you try your hardest to make it come true.", "\"Neko-Pan and the Maneki-Neko Shrine\" [Neko-Pan] :: At a temple covered in hundreds of beckoning-cat statues, Neko-Pan returns a lost lucky charm to its owner and the whole grateful row of cats seems to wave.", "\"Tama Onigiri and the Festival Fox Mask\" [Tama Onigiri] :: At a bustling summer festival, comforting Tama Onigiri shares packed rice balls with a shy friend hiding behind a cute fox mask, and helps them find the courage to play.", "\"Pock Ramune and the Festival Goldfish Scoop\" [Pock Ramune] :: Fizzy Pock Ramune learns that the festival goldfish game rewards a soft, patient scoop, and he gently helps a smaller friend win their very first goldfish.", "\"The Dango Three and the Portable-Shrine Parade\" [The Dango Three] :: The three dango each grab a corner of a tiny portable shrine and learn that a heavy, joyful load becomes light when shouldered together with a happy chant.", "\"Rin Ramen and the Lucky Omikuji\" [Rin Ramen] :: When Rin Ramen draws a so-so fortune at the shrine, his friends show him that a warm bowl shared makes any day a 'great blessing' no matter what the paper says.", "\"Niko Nigiri and the Cherry Blossom Picnic\" [Niko Nigiri] :: Niko organizes the perfect hanami picnic, then learns to put down his checklist and simply watch the pink petals drift like soft snow over his friends.", "\"Momo Mochi and the Pink Petal Snow\" [Momo Mochi] :: Squishy Momo Mochi tries to catch every falling petal, then realizes the magic is just lying back with friends and letting the pink snow land where it likes.", "\"Kori Kakigori and the Summer Meltdown\" [Kori Kakigori] :: Dramatic shaved-ice Kori is convinced she'll melt away on the hottest day of summer, until her friends build a shady fort and keep her sweet and frosty.", "\"Tako and Yaki and the Summer Fireworks\" [Tako & Yaki] :: The takoyaki twins each want to watch the fireworks from a different spot, then discover that the show is twice as sparkly when they 'ooh' and 'aah' side by side.", "\"Kuma Kuri and the Autumn Leaf Trail\" [Kuma the Kuri] :: Chestnut Kuma feels sad that summer is ending, but a walk through fiery red momiji leaves teaches him that autumn has a cozy, crackly magic all its own.", "\"Yuki and the First Snowfall\" [Yuki the Snow Monkey-Manju] :: Snow-loving Yuki wakes everyone for the first snowfall of winter, and the whole sleepy cast tumbles out to make tiny snow-friends in the hush of the white morning.", "\"Maru Matcha and the Carp Streamers\" [Maru Matcha] :: Maru Matcha helps a shy little friend raise a carp streamer for the first time, and they watch it swim bravely up the spring wind like a wish taking flight.", "\"Sora Soft-Cream and the Winter Illuminations\" [Sora the Soft-Cream] :: Gentle Sora bundles up against the cold to wander a sparkling winter light festival, learning that the chilliest night can shine the brightest with friends near.", "\"Rin Ramen and the Secret Broth Recipe\" [Rin Ramen] :: Rin Ramen begs a famous ramen master to share the legendary secret broth recipe, only to discover the real secret is the love simmered slowly into every pot.", "\"Pepper-kun and the Sizzling Showdown\" [Pepper-kun] :: Showman Pepper-kun stages a dramatic sizzling-beef cook-off to be the loudest plate in the food court, then learns the crowd loves him most when he shares every bite.", "\"Tako and Yaki and the Osaka Takoyaki Stand\" [Tako & Yaki] :: The takoyaki twins run their own little stall and learn to flip a tray of sizzling batter balls in perfect twin-time, turning chaos into a delicious dance.", "\"Tai Taiyaki and the Riverside Stall\" [Tai Taiyaki] :: Adventurous Tai Taiyaki dreams of 'swimming' in a real river, and his friends help him take a gentle, splashy dip before he proudly returns warm and sweet.", "\"Coro Korokke and the Bakery Rush\" [Coro the Korokke] :: Humble Coro Korokke saves the morning rush at a frazzled bakery by calmly organizing the crispy snacks and warm bread, proving small helpers matter most.", "\"Mero Melonpan and the Sleepy Bakery Dream\" [Mero Melonpan] :: Dreamy Mero Melonpan dozes off in a cozy bakery and his friends gently follow his sleepy daydream of a kingdom made of warm, crackly sweet bread.", "\"Niko Nigiri and the Conveyor-Belt Sushi\" [Niko Nigiri] :: Tidy Niko visits a conveyor-belt sushi place and learns to relax and enjoy the surprise of whatever delicious little plate comes spinning around next.", "\"Tama Onigiri and the Bento-Box Balance\" [Tama Onigiri] :: Tama Onigiri helps friends pack the most balanced, colorful bento boxes and discovers that the best lunch has a little bit of everyone's favorite inside.", "\"Rin Ramen and the Slurpy Udon Race\" [Rin Ramen] :: When Rin challenges friends to a fast udon-slurping race, a gentle udon elder teaches them that the chewiest, warmest noodles are best enjoyed slowly.", "\"Momo Mochi and the Shinkansen Departure\" [Momo Mochi] :: The whole cast boards the lightning-fast bullet train for a grand cross-country trip, and Momo Mochi calms first-trip jitters with a cozy window-seat squish.", "\"Sora Soft-Cream and the Hokkaido Milk Farm\" [Sora the Soft-Cream] :: Soft-serve Sora visits the wide Hokkaido dairy fields where she was 'born,' and learns that the creamiest comfort comes from wide skies and slow, happy cows.", "\"The Grand Half-Way Festival of Friends\" [Momo Mochi] :: At the halfway point of their travels, the entire cast throws a huge joyful festival to celebrate fifty stories of friendship, with food, fireworks, and a thousand lanterns.", "\"Tako and Yaki and the Osaka Castle Adventure\" [Tako & Yaki] :: The takoyaki twins explore towering Osaka Castle and turn a history lesson into a giggly treasure hunt for the castle's shiniest golden dolphin.", "\"Kuma Kuri and the Nara Deer Bows\" [Kuma the Kuri] :: Shy Kuma Kuri meets the famous bowing deer of Nara and learns that a polite little bow back is the friendliest hello of all.", "\"Niko Nigiri and the Kyoto Kimono Day\" [Niko Nigiri] :: Niko Nigiri carefully tries on a beautiful kimono to stroll old Kyoto, learning that taking your time with tradition makes a day feel truly special.", "\"Maru Matcha and the Tea Ceremony\" [Maru Matcha] :: Calm Maru Matcha hosts her very first tea ceremony for her friends, sharing the quiet, beautiful art of whisking and serving one perfect bowl of tea.", "\"Momo Mochi and the Yukata Summer Stroll\" [Momo Mochi] :: Squishy Momo Mochi wears a breezy summer yukata to a riverside festival and helps a friend tie a wobbly sash, proving cozy and pretty are the perfect pair.", "\"Sen Senbei and the Summer Wind-Chimes\" [Sen the Senbei] :: Plain little Sen the Senbei, sure he is too small to make anything that matters, is invited by a translucent glassblower to paint glass wind-chimes and write kind notes on their paper tails — chimes that will be taken home by anonymous strangers — and witnesses a tired dumpling-child choose his bell and smile, discovering that an anonymous handmade kindness is one of the biggest things there is.", "\"Kuma Kuri and the Golden Pavilion\" [Kuma the Kuri] :: At the dazzling Golden Pavilion, modest Kuma feels too plain beside all the gold, until friends remind him his cozy roasted warmth is its own kind of treasure.", "\"Kompei and the Indigo Dye Workshop\" [Kompei the Konpeito] :: Perfection-obsessed Kompei goes to an indigo-dyeing workshop wanting one flawless even-blue square, but when his clumsy hand slips and bunches the cloth, the accident blooms into a stunning unplanned star-pattern — and he learns to make 'real' instead of 'perfect,' even painting a pattern by sitting on the cloth.", "\"Dai Daruma and the Calligraphy Brush\" [Dai Daruma] :: Determined Dai Daruma wobbles his way through writing his first big brush-stroke character, learning that a brave, splotchy first try is something to celebrate.", "\"Sora Soft-Cream and the Sapporo Snow Festival\" [Sora the Soft-Cream] :: In snowy Sapporo, gentle Sora joins friends to build a towering snow sculpture, learning that even the grandest creation starts with one small, careful scoop.", "\"Yuki and the Hokkaido Snow Lanterns\" [Yuki the Snow Monkey-Manju] :: Snow-loving Yuki helps light a row of little ice-and-candle lanterns along a frosty canal, turning a freezing night into a warm and glowing wonderland.", "\"Tako and Yaki and the Okinawa Blue Sea\" [Tako & Yaki] :: The takoyaki twins splash into the warm blue Okinawa sea and make friends with a gentle sea turtle, learning the ocean is one big playground for two.", "\"Tai Taiyaki and the Okinawa Coral Reef\" [Tai Taiyaki] :: Fish-cake Tai Taiyaki finally meets real fish at a giant aquarium and the dazzling reef teaches him that being a little different makes you wonderfully special.", "\"Pepper-kun and the Osaka Food Street\" [Pepper-kun] :: Sizzling Pepper-kun explores Osaka's famous food street and teams up with an okonomiyaki cook to feed a hungry, happy crowd late into the glowing night.", "\"Coro Korokke and the Hokkaido Potato Fields\" [Coro the Korokke] :: Humble Coro Korokke visits the wide Hokkaido potato fields where his fluffy heart began, and learns to feel proud of his simple, comforting roots.", "\"Niko Nigiri and the Tsukiji Morning Market\" [Niko Nigiri] :: Niko Nigiri wakes before dawn to explore the busy morning market and learns from the kind vendors that the freshest, brightest days belong to early risers.", "\"Momo Mochi and the New-Year Mochi Pounding\" [Momo Mochi] :: At the New Year mochi-pounding festival, Momo Mochi cheers as friends take turns with the big wooden mallet, celebrating fresh starts with sticky, squishy joy.", "\"Dai Daruma and the New-Year First Shrine Visit\" [Dai Daruma] :: On the first shrine visit of the year, Dai Daruma helps friends choose hopeful New Year wishes and reminds everyone that a new year means a brand-new bounce.", "\"Tama Onigiri and the Bean-Throwing Day\" [Tama Onigiri] :: On bean-throwing day, comforting Tama Onigiri befriends a shy, cuddly little oni who only wanted to join the fun, turning the custom into a game of welcome.", "\"The Dango Three and the Doll Festival\" [The Dango Three] :: The three dango help arrange the tiered doll display for the spring Doll Festival and make sure even the smallest, dustiest doll gets a place of honor.", "\"Tai Taiyaki and the Children's Day Carp\" [Tai Taiyaki] :: On Children's Day, fish-cake Tai Taiyaki races the giant carp streamers up the hill and learns that swimming your own brave direction is how you grow up strong.", "\"Mero Melonpan and the Tanabata Wishes\" [Mero Melonpan] :: Dreamy Mero Melonpan helps friends write their summer star-festival wishes on colorful papers and tie them to a bamboo branch reaching up toward the Milky Way.", "\"Maru Matcha and the Moon-Viewing Night\" [Maru Matcha] :: Calm Maru Matcha gathers friends for an autumn moon-viewing picnic with round dumplings, and they spot the gentle 'rabbit' said to live on the bright full moon.", "\"Momo Mochi and the Warm Winter-Solstice Bath\" [Momo Mochi] :: On the longest, coldest night, squishy Momo Mochi shares the cozy custom of a yuzu-citrus bath, filling the bathhouse with golden fruit and warm giggles.", "\"Kuma Kuri and the Friendly Forest Spirit\" [Kuma the Kuri] :: Shy Kuma Kuri meets an equally shy, fluffy little forest spirit, and the two quiet friends discover that being bashful together is the start of a sweet friendship.", "\"Maru Matcha and the Tea-Loving Tanuki\" [Maru Matcha] :: A playful, pot-bellied tanuki keeps sneaking sips of Maru Matcha's tea, until she simply invites him to sit and share a proper cup, turning mischief into friendship.", "\"Tama Onigiri and the Shy Kappa of the Pond\" [Tama Onigiri] :: Comforting Tama Onigiri leaves a tiny rice ball by the pond for a bashful, cucumber-loving kappa, and a careful, kind friendship blossoms over shared snacks.", "\"Dora Dorayaki and the Lantern-Lighting Spirits\" [Dora the Dorayaki] :: Story-keeper Dora helps tiny friendly spirits guide their glowing paper lanterns down a gentle river, learning that warm memories light the softest, kindest path.", "\"Neko-Pan and the Lucky Beckoning Spirits\" [Neko-Pan] :: Neko-Pan meets a family of cheerful little luck-spirits who have run out of good fortune to give, and helps them refill their kindness by spreading joy all day.", "\"Mero Melonpan and the Dream-Eating Baku\" [Mero Melonpan] :: When a friend has a worried little dream, sleepy Mero Melonpan introduces a soft, friendly baku who gently nibbles away the worry and leaves only sweet dreams.", "\"Pock Ramune and the Summer Cicada Chorus\" [Pock Ramune] :: Fizzy Pock Ramune wants to find the loudest cicada of summer, but learns that the buzzing hillside sounds best when every little voice sings together.", "\"Kuma Kuri and the Rice-Paddy Fireflies\" [Kuma the Kuri] :: Shy Kuma Kuri sits quietly by the glowing rice paddies as hundreds of gentle fireflies rise, discovering that even tiny, bashful lights can fill a whole valley.", "\"Sora Soft-Cream and the Lavender Fields\" [Sora the Soft-Cream] :: Gentle Sora drifts through endless purple lavender fields and helps friends notice the soft buzzing bees, the sweet scent, and the slow joy of a sunny afternoon.", "\"Tama Onigiri and the Rice-Harvest Helpers\" [Tama Onigiri] :: Rice-ball Tama Onigiri joins the autumn harvest and learns the long, happy journey from golden field to warm bowl, thanking every helper along the way.", "\"Maru Matcha and the Tea-Hill Morning\" [Maru Matcha] :: Calm Maru Matcha wakes at dawn to walk the misty rows of her home tea hills, sharing with friends the peaceful, dewy green hush of the very early morning.", "\"Tako and Yaki and the Koi Pond Friends\" [Tako & Yaki] :: The bouncy takoyaki twins befriend the slow, graceful koi of a garden pond and learn that there's a happy place between zooming around and drifting peacefully.", "\"Yuki and the Snow-Country Village\" [Yuki the Snow Monkey-Manju] :: Snuggly Yuki visits a storybook snow village of steep thatched roofs and learns how the whole community helps shovel, share, and stay cozy through the long winter.", "\"Pepper-kun and the Midnight Garage\" [Pepper-kun] :: Sizzly Pepper-kun helps the friends gently tune up a sleepy little kei-truck in a warm neon garage, learning that the magic is in the loving details.", "\"Niko Nigiri and the Neon Car Meet\" [Niko Nigiri] :: Tidy Niko parks the little Sushi-ya Express food truck at a friendly glowing car meet and discovers that everyone's ride is wonderfully different.", "\"The Sushi-ya Express and the Touge Sunrise\" [The Sushi-ya Express] :: The sushi-truck crew takes a gentle, careful dawn drive up a misty mountain pass to deliver the freshest sunrise breakfast sushi.", "\"Tako and Yaki and the Time-Attack Circuit\" [Tako and Yaki] :: The takoyaki twins enter a friendly, careful time-attack and learn that smooth teamwork and giggles matter more than being fastest.", "\"Dai Daruma and the Lucky Dashboard Charm\" [Dai Daruma] :: Dai Daruma becomes the good-luck charm swinging from the mirror of a lovingly restored classic car, beaming over the friends who fixed it up together.", "\"Coro Korokke and the Neighborhood Clean-Up Day\" [Coro the Korokke] :: Humble Coro Korokke rallies the cast for a neighborhood tidy-up, and the quiet good deed turns into a joyful, sparkling morning that brings the whole street together.", "\"Niko Nigiri and the Omiyage Souvenir Quest\" [Niko Nigiri] :: As the journey nears its end, organized Niko sets out to buy the perfect souvenir treat for each friend, learning that the best gift is one chosen with the heart.", "\"Rin Ramen and the Farewell Feast\" [Rin Ramen] :: Hearty Rin Ramen cooks a giant warm feast for the whole cast before the journey ends, and the steaming, slurpy table becomes a celebration of everything they've shared.", "\"Tai Taiyaki and the Last Sunrise by the Sea\" [Tai Taiyaki] :: Brave Tai Taiyaki leads friends to watch one last sunrise over the sea, learning that the end of an adventure is really the bright beginning of the next.", "\"Maru Matcha and the Thank-You Tea\" [Maru Matcha] :: Calm Maru Matcha hosts a gentle thank-you tea, whisking a cup for each friend and helping the whole cast share what they're most grateful for from the journey.", "\"Dai Daruma and the Second Painted Eye\" [Dai Daruma] :: At the journey's close, determined Dai Daruma finally paints in his daruma's second eye, celebrating with friends that the brave wish made long ago has come true.", "\"Momo Mochi and the Final Shinkansen Home\" [Momo Mochi] :: Squishy Momo Mochi rides the bullet train home one last time, watching Mount Fuji glow at sunset and realizing the whole journey gave her a hundred new homes-in-the-heart.", "\"The Grand Rising-Sun Reunion\" [Momo Mochi] :: The entire kawaii cast gathers for a dazzling grand reunion festival under the Tokyo lights, with onsen steam, lanterns, fireworks, and every friend they made, before a soft and sleepy goodnight to all of Japan."]};
phase('Dedup recheck')
const DUP = { type:'object', additionalProperties:false, required:['clusters'],
  properties:{ clusters:{ type:'array', items:{ type:'object', additionalProperties:false, required:['titles','reason','severity'],
    properties:{ titles:{type:'array',items:{type:'string'}}, reason:{type:'string'}, severity:{type:'string',enum:['low','med','high']} } } } } }
const cols=Object.keys(LISTS)
const res=await parallel(cols.map(c=>()=>agent(
  `These are all stories in the "${c}" bedtime collection (title [character] :: premise). Find any that remain TRUE near-duplicates in premise AND lesson (same setup + same arc/lesson). Do NOT flag mere shared character/setting/broad theme. Return only genuine high/med overlaps.\n\n${LISTS[c].map((x,i)=>`${i+1}. ${x}`).join('\n')}`,
  {label:`recheck:${c}`, phase:'Dedup recheck', schema:DUP}).then(r=>({c,clusters:(r.clusters||[]).filter(k=>k.severity!=='low')})).catch(()=>({c,clusters:[]}))))
log('recheck: '+JSON.stringify(res.map(r=>({c:r.c,clusters:r.clusters.length}))))
return {res}
